# IDUM 5 (ч. 1 и 2): сверка с ответами учебника (текстовый слой PDF, по содержанию) + пересчёт каждого ключа. 26.09
P = {}
S1, S2 = "IDUM 5 ч. 1 (текст PDF + ответы)", "IDUM 5 ч. 2 (текст PDF + ответы)"
def E(t, why, src, **kw): P[t] = dict(why=why, src=src + " + пересчёт, 26.09", **kw)
MIS = "опечатка в учебнике исправлена по смыслу (решение владельца 25.09): "
E("G5_TB_12_209.2", MIS + "в учебнике «674 330 : 306» не делится нацело, ответ учебника «в 2205 раз» соответствует числу 674 730 (306 · 2205 = 674 730); ключ был текстом рассуждения «в 2203,69 раз (возможно опечатка…)»",
  S1, q=r"Во сколько раз число $306$ меньше числа $674\,730$?", k=r"в $2205$ раз",
  dnew={0: (r"на $674\,424$", "Ученик нашёл разность чисел, а не их отношение."), 1: (r"в $225$ раз", "Ученик потерял нуль в частном при делении уголком."),
        2: (r"в $2250$ раз", "Ученик ошибся в последней цифре частного.")})
E("G5_TB_24_419", MIS + "вопрос учебника «сколько продано за эти два дня?» повторяет данное (1020 кг); по ответу учебника (680 кг; 340 кг) спрашивается продажа каждого дня; ключ был 1020 кг",
  S1, q=r"За два дня в магазине было продано $1020$ кг картофеля. В первый день продано в $2$ раза меньше картофеля, чем во второй день. Сколько картофеля было продано в каждый из этих дней?",
  k=r"в первый день — $340$ кг, во второй — $680$ кг",
  dnew={0: (r"в первый день — $680$ кг, во второй — $340$ кг", "Ученик перепутал, в какой день продали больше."),
        1: (r"в первый день — $510$ кг, во второй — $510$ кг", "Ученик разделил массу поровну, не учтя, что во второй день продали вдвое больше."),
        2: (r"в первый день — $255$ кг, во второй — $765$ кг", "Ученик разделил 1020 на 4 части вместо 3 (1 + 2).")})
E("G5_TB_15_284", "ключ был округлён (2,22): 1500 : (15 · 45) = 1500 : 675 = 20/9 = 2 2/9", S1, k=r"$2\dfrac{2}{9}$")
E("G5_TB_25_448", "тире в тексте превратилось в минус («длина −18 дм»)", S1, q=r"Периметр прямоугольника равен $64$ дм, а длина — $18$ дм. Найдите ширину.")
E("G5_TB_15_290", "тире в тексте превратилось в минус («для детей −12000 сум»)", S1, q=r"Билет в театр для взрослых стоит $25000$ сум, а для детей — $12000$ сум. В семье двое взрослых и трое детей. Сколько должна заплатить за билеты семья?")
E("G5_TB_30_518", "в ключе не было единиц измерения: 6 · 15 = 90 м², 90 · 200 г = 18 000 г = 18 кг (ответ учебника 18 кг)", S1, k=r"$18000$ г ($18$ кг)")
E("G5_TB_61_1444", "ключ неверен: первое число 3,062 − 1,922 = 1,14, третье 3,062 − 0,18 = 2,882, четвёртое 16,712 − 1,14 − 3,062 − 2,882 = 9,628; 9,628 − 3,062 = 6,566 (совпадает с ответом учебника № 421; было 6,56)",
  S2, k=r"$6{,}566$", dadd=[(r"$6{,}56$", "прежний неверный ключ: ошибка при вычитании")])
E("G5_TB_38_672.1", "ключ неверен: длина 32,9 дм, ширина 32,9 − 2,2 = 30,7 дм, площадь 32,9 · 30,7 = 1010,03 дм² (было 1009,93); вариант «1010.03» был верным ответом среди неверных — закрыт",
  S2, k=r"$1010{,}03$ дм$^{2}$", drop=[0], dadd=[(r"$1009{,}93$ дм$^{2}$", "прежний неверный ключ: ошибка при умножении")])
E("G5_TB_55_1311", "тире в тексте превратились в минусы («высоту −2 м и толщину −40 см»)", S2,
  q=r"Кирпичная стена имеет длину $30$ м, высоту — $2$ м и толщину — $40$ см. Кирпич имеет измерения: $30$ см, $15$ см, $10$ см. Сколько кирпичей необходимо для возведения стены?")
E("G5_TB_64_1565.1", "десятичная дробь 5,3 разорвана на «5 см, 3 см» (сверено с учебником № 507 а)); ключ 31,8 соответствует 5,3 · 6", S2,
  q=r"Найдите площадь прямоугольника, если его стороны равны $5{,}3$ см и $6$ см.")
E("G5_TB_56_1322", MIS + "в учебнике (№ 322) при «в третий день на 56 000 меньше, чем в первый» ответ нецелый (ключ был 683 666,67…); ответ учебника (691 500, 668 000, 612 000 сум) соответствует «меньше, чем во второй день»: 691 500 − 668 000 = 23 500, 668 000 − 56 000 = 612 000",
  S2, q=r"За три дня магазин реализовал товар на $1\,971\,500$ сум. Если в первый день было продано на $23\,500$ сум больше, чем во второй, а в третий день на $56\,000$ сум меньше, чем во второй день, то на какую сумму было продано товара каждый день?",
  k=r"в первый день — $691\,500$ сум, во второй — $668\,000$ сум, в третий — $612\,000$ сум",
  dnew={0: (r"в первый день — $668\,000$ сум, во второй — $691\,500$ сум, в третий — $612\,000$ сум", "Ученик перепутал первый и второй день: в первый день продали больше."),
        1: (r"в первый день — $683\,666{,}67$ сум, во второй — $660\,166{,}67$ сум, в третий — $627\,666{,}67$ сум", "Ученик сравнил третий день с первым, а не со вторым."),
        2: (r"по $657\,166{,}67$ сум каждый день", "Ученик разделил выручку поровну, не учитывая условия.")})
